def minCapability(nums, k):
    # Helper: Can you rob at least k non-adjacent houses with max amount ≤cap?
    def can_rob(cap):
        count = 0
        i = 0
        n = len(nums)
        while i < n:
            if nums[i] <= cap:
                count += 1
                i += 2  # skip adjacent
            else:
                i += 1
            if count >= k:
                return True
        return False

    left = min(nums)
    right = max(nums)
    ans = right

    while left <= right:
        mid = (left + right) // 2
        if can_rob(mid):
            ans = mid
            right = mid - 1  # try to improve (minimize capability)
        else:
            left = mid + 1
    return ans
